        result = deserializer(obj)

    # Convert _iterable_opcodes from dicts to Opcode objects
    if result.get('_iterable_opcodes'):
        _iterable_opcodes = {}
        for path, op_codes in result['_iterable_opcodes'].items():
            _iterable_opcodes[path] = []
